import type { SyllabusTopic } from './topics';

export interface CourseUnit {
  title: string;
  objective: string;
  lesson: string;
  example: string;
  examFocus: string;
}

export const courseUnits: Record<string, [CourseUnit, CourseUnit, CourseUnit]> = {
  'pt-interpretacao': [
    { title: 'Entenda o que o texto diz', objective: 'Localizar tema, finalidade e informação expressa.', lesson: 'Leia primeiro o texto inteiro para formar uma ideia geral. Tema é o assunto central; finalidade é o que o texto pretende fazer, como informar, orientar, defender uma ideia ou solicitar uma providência. Depois volte ao enunciado e procure a frase que sustenta a resposta. Uma alternativa correta precisa caber no texto todo, não apenas em uma palavra isolada.', example: 'Se um aviso informa que o protocolo mudou de horário para reduzir filas, o tema é a alteração do atendimento e a finalidade é orientar o público. O aviso não afirma que o serviço foi encerrado.', examFocus: 'Separe tema de finalidade e prefira a alternativa que possa ser comprovada por trecho do texto.' },
    { title: 'Relacione as ideias', objective: 'Reconhecer causa, consequência, oposição, condição e conclusão.', lesson: 'A interpretação depende das relações entre frases. Conectivos como “porque” indicam causa; “portanto”, conclusão; “mas”, oposição; “se”, condição. Pronomes e expressões como “essa medida” retomam informações anteriores. Identifique a que termo cada palavra se refere antes de concluir o sentido.', example: '“O sistema foi atualizado, mas o atendimento presencial continua.” A conjunção “mas” contrapõe a atualização à continuidade do atendimento.', examFocus: 'Observe conectivos, pronomes de retomada e a sequência lógica das informações.' },
    { title: 'Faça inferências autorizadas', objective: 'Concluir apenas o que decorre das pistas do texto.', lesson: 'Inferir é chegar a uma conclusão que o texto permite, mesmo que ela não apareça com as mesmas palavras. Não é completar a história com opinião ou conhecimento externo. Uma boa inferência tem pistas identificáveis e não transforma possibilidade em certeza absoluta.', example: 'Se o texto diz que o cidadão pode acompanhar o processo sem ir ao balcão, é autorizado concluir que a medida reduz deslocamentos; não é autorizado concluir que todo atendimento presencial acabou.', examFocus: 'Desconfie de alternativas com “sempre”, “somente”, “todos” ou “nunca” quando o texto não usa essa ideia.' }
  ],
  'pt-vocabulario': [
    { title: 'Sentido literal e figurado', objective: 'Distinguir denotação, conotação e contexto.', lesson: 'Denotação é o sentido mais direto da palavra; conotação é o sentido figurado criado pelo contexto. A mesma palavra pode mudar de sentido conforme a frase. Antes de escolher um sinônimo, substitua-o mentalmente no trecho e confira se o tom e a ideia continuam iguais.', example: '“A porta está aberta” usa sentido literal. “A prefeitura abriu as portas à participação” usa “abriu as portas” figuradamente: permitiu ou incentivou a participação.', examFocus: 'O contexto determina o sentido; sinônimos raramente são intercambiáveis em qualquer frase.' },
    { title: 'Compare relações entre palavras', objective: 'Identificar sinonímia, antonímia e polissemia.', lesson: 'Sinônimos têm sentidos próximos, mas podem diferir em intensidade ou uso. Antônimos expressam oposição. Polissemia ocorre quando uma mesma palavra assume sentidos relacionados em contextos diferentes. Não confunda polissemia com palavras diferentes que apenas têm forma igual.', example: '“Claro” pode significar luminoso ou fácil de compreender: há mais de um sentido para a mesma palavra. “Deferir” e “diferir” têm forma parecida, mas significados distintos.', examFocus: 'Analise a palavra dentro da frase e diferencie sentido múltiplo de semelhança sonora ou gráfica.' },
    { title: 'Evite confusões de forma', objective: 'Diferenciar homônimos, parônimos e substituições inadequadas.', lesson: 'Homônimos têm igualdade de som e/ou escrita, mas sentidos distintos. Parônimos são parecidos na escrita ou pronúncia e também têm sentidos diferentes. Em questões, a banca costuma trocar um termo por outro próximo para testar precisão. Releia a frase após qualquer substituição.', example: '“Ratificar” é confirmar; “retificar” é corrigir. A semelhança não autoriza a troca.', examFocus: 'Confirme o significado preciso e o efeito da substituição no contexto.' }
  ],
  'pt-ortografia': [
    { title: 'Escreva conforme a norma atual', objective: 'Reconhecer grafias corretas e regularidades ortográficas.', lesson: 'A ortografia oficial define a forma escrita das palavras; muitas grafias precisam ser aprendidas pelo uso e pela consulta a fonte confiável. Observe famílias de palavras e formação por prefixos. Não deduza a grafia apenas pela pronúncia, que varia regionalmente.', example: '“Pesquisa” e “pesquisar” mantêm o mesmo radical. Em dúvida sobre uma palavra de uso menos comum, consulte um vocabulário ortográfico atualizado.', examFocus: 'A prova pode apresentar pares parecidos; leia cada palavra completa e considere o sentido da frase.' },
    { title: 'Aplique as regras de acentuação', objective: 'Classificar palavras e justificar o acento gráfico.', lesson: 'Separe a palavra em sílabas e localize a sílaba tônica. Oxítonas têm a última sílaba tônica; paroxítonas, a penúltima; proparoxítonas, a antepenúltima. A regra de acentuação depende dessa posição e da terminação. Hiatos e ditongos seguem regras próprias, com exceções previstas na ortografia vigente.', example: 'Em “público”, a tonicidade recai na antepenúltima sílaba, por isso a palavra é proparoxítona; todas as proparoxítonas são acentuadas.', examFocus: 'Não acentue pelo som apenas: classifique a tonicidade e aplique a regra correspondente.' },
    { title: 'Resolva casos de prova', objective: 'Analisar acentuação, hífen e grafias concorrentes com método.', lesson: 'Em itens combinados, verifique cada palavra separadamente: grafia, tonicidade e regra. O Acordo Ortográfico alterou alguns usos de hífen e acentos diferenciais; por isso, use a norma atual e não uma regra lembrada pela metade. Uma alternativa só está correta se todos os casos apresentados estiverem corretos.', example: 'Em uma lista com três palavras, marque cada uma como certa ou errada antes de avaliar a alternativa. Um único erro torna a lista inteira incorreta.', examFocus: 'Divida o item em afirmações pequenas e procure exceções da regra.' }
  ],
  'pt-pontuacao': [
    { title: 'Dê estrutura à frase', objective: 'Empregar ponto, vírgula e dois-pontos em usos básicos.', lesson: 'A pontuação organiza a leitura e sinaliza relações sintáticas. O ponto encerra uma declaração; os dois-pontos anunciam explicação, enumeração ou fala; a vírgula separa elementos, intercalações e certas orações. A vírgula não deve separar sujeito e verbo nem verbo e complemento quando a ordem é direta.', example: '“A equipe recebeu o pedido, conferiu os documentos e encaminhou o processo.” A enumeração de ações não exige vírgula entre sujeito e primeiro verbo.', examFocus: 'Localize sujeito, verbo e complementos antes de decidir onde a vírgula cabe.' },
    { title: 'Interprete pausas e intercalações', objective: 'Usar vírgulas em enumerações, vocativos e termos explicativos.', lesson: 'A vírgula pode isolar vocativo, aposto explicativo e expressão intercalada. Em enumeração, separa itens coordenados. Orações adverbiais deslocadas costumam ser separadas por vírgula; quando vêm no fim, a pontuação depende da estrutura e do sentido. Pausa da fala ajuda, mas não substitui a análise gramatical.', example: '“Senhora, seu protocolo foi recebido.” “Senhora” é vocativo e fica isolado; não é o sujeito da oração.', examFocus: 'Pergunte se o termo é chamamento, explicação ou elemento da enumeração.' },
    { title: 'Perceba mudança de sentido', objective: 'Avaliar pontuação em períodos complexos sem alterar a ideia.', lesson: 'A pontuação pode tornar uma informação explicativa ou restritiva, mudar o alcance de um termo e separar orações com relações diferentes. Ao reescrever uma frase, compare quem está incluído, o que é explicado e a que oração cada conectivo se liga.', example: '“Os servidores, que concluíram o curso, receberam certificado” sugere que todos os servidores mencionados concluíram. Sem as vírgulas, a oração pode delimitar apenas quais servidores receberam certificado.', examFocus: 'Leia as duas versões e diga precisamente qual informação foi incluída, excluída ou destacada.' }
  ],
  'pt-classes': [
    { title: 'Reconheça a função das palavras', objective: 'Distinguir substantivo, adjetivo, pronome e verbo no contexto.', lesson: 'Classe gramatical não depende só da forma: observe o papel da palavra na frase. Substantivo nomeia; adjetivo caracteriza; pronome acompanha ou substitui um nome; verbo expressa ação, estado ou fenômeno e se flexiona em tempo, modo, pessoa e número. Uma mesma forma pode pertencer a classes diferentes em contextos distintos.', example: 'Em “o atendimento rápido”, “atendimento” é substantivo e “rápido” é adjetivo; em “atenda rapidamente”, “atenda” é verbo.', examFocus: 'Classifique pelo uso na frase, não por uma lista decorada fora de contexto.' },
    { title: 'Use pronomes, verbos e conectivos', objective: 'Analisar colocação pronominal, flexão verbal e relações de preposição e conjunção.', lesson: 'Pronomes retomam nomes e evitam repetição. Na colocação pronominal, palavras atrativas como negativas e certos pronomes favorecem próclise; a ênclise e a mesóclise têm contextos formais específicos. Verbos flexionam conforme sujeito, tempo e modo; preposições criam relações como origem, meio ou assunto; conjunções conectam orações e indicam causa, oposição, condição ou conclusão.', example: '“Embora o prazo fosse curto, a equipe concluiu o serviço”: “embora” introduz concessão, uma dificuldade que não impediu o resultado.', examFocus: 'Identifique o antecedente do pronome, o sujeito do verbo e o sentido do conectivo.' },
    { title: 'Resolva casos de flexão e emprego', objective: 'Interpretar formas verbais e nominalização em períodos de prova.', lesson: 'Verbos irregulares alteram o radical ou a terminação em parte da conjugação; abundantes têm mais de uma forma de particípio em certos usos; defectivos não apresentam todas as formas no uso padrão. Voz ativa põe o sujeito como agente; passiva destaca o paciente. Substantivos e adjetivos também variam em gênero, número e grau conforme a construção.', example: '“A unidade publicou o aviso” está na voz ativa; “o aviso foi publicado pela unidade” está na passiva analítica. O fato central permanece, mas o foco sintático muda.', examFocus: 'Confira concordância, valor do tempo e modo verbal e transformação entre vozes.' }
  ],
  'pt-termos': [
    { title: 'Encontre o núcleo da oração', objective: 'Localizar sujeito, predicado e verbo principal.', lesson: 'Comece pelo verbo e pergunte quem ou o que pratica, sofre ou apresenta o estado expresso. Sujeito é o termo com o qual o verbo concorda; predicado é o que se declara sobre o sujeito. Há sujeito simples, composto, oculto, indeterminado e oração sem sujeito, conforme a construção.', example: '“Chegaram ao protocolo os documentos solicitados.” O verbo está no plural e o sujeito é “os documentos solicitados”, embora apareça depois dele.', examFocus: 'Não confunda o primeiro nome da frase com o sujeito; use concordância e sentido.' },
    { title: 'Classifique complementos e adjuntos', objective: 'Diferenciar objetos, complemento nominal, predicativo e modificadores.', lesson: 'Objeto direto completa verbo sem preposição exigida; objeto indireto completa verbo com preposição. Complemento nominal completa um nome, adjetivo ou advérbio. Adjunto adnominal caracteriza ou determina um substantivo; adjunto adverbial indica circunstância. Predicativo atribui estado ou qualidade ao sujeito ou objeto.', example: 'Em “a equipe analisou o requerimento com cuidado”, “o requerimento” completa o verbo e “com cuidado” indica modo.', examFocus: 'Pergunte a que palavra o termo se liga e que tipo de sentido acrescenta.' },
    { title: 'Analise estruturas ambíguas', objective: 'Usar regência, voz e contexto para classificar termos próximos.', lesson: 'A mesma preposição pode introduzir funções diferentes. Um termo ligado a substantivo pode ser complemento nominal ou adjunto adnominal; um termo que caracteriza pode ser predicativo ou adjunto. A diferença vem do sentido, da regência e da relação com o restante da oração.', example: 'Em “a crítica do servidor ao sistema”, “ao sistema” indica o alvo da crítica; em “o relatório do servidor”, “do servidor” pode indicar autoria ou posse, conforme o contexto.', examFocus: 'Substitua mentalmente o termo por uma pergunta: quem pratica, quem recebe, a quem se atribui ou em que circunstância?' }
  ],
  'pt-coordenacao': [
    { title: 'Una orações independentes', objective: 'Reconhecer coordenação e relações entre orações.', lesson: 'Orações coordenadas são sintaticamente independentes: uma não exerce função sintática dentro da outra. Podem aparecer lado a lado sem conjunção ou ligadas por conectivo. As coordenadas sindéticas expressam adição, oposição, alternância, conclusão ou explicação.', example: '“O setor recebeu o documento e registrou a solicitação.” A conjunção “e” soma duas ações coordenadas.', examFocus: 'Leia a relação lógica entre as ações, não apenas o nome da conjunção.' },
    { title: 'Subordine uma ideia a outra', objective: 'Distinguir oração principal e subordinada e seus valores.', lesson: 'Na subordinação, uma oração depende de outra e pode funcionar como substantivo, adjetivo ou advérbio. Orações substantivas ocupam funções como sujeito ou complemento; adjetivas caracterizam um nome; adverbiais indicam circunstâncias como causa, condição, concessão, finalidade e tempo.', example: '“A equipe informou que o sistema voltou.” A oração “que o sistema voltou” completa o sentido do verbo informar.', examFocus: 'Teste se a oração subordinada pode ser substituída por “isso”, por um adjetivo ou por uma circunstância.' },
    { title: 'Interprete conectivos e efeitos', objective: 'Resolver questões de reescrita sem trocar a relação semântica.', lesson: 'A conjunção sinaliza a relação, mas o contexto confirma o valor. “Como” pode indicar causa ou comparação; “pois” pode explicar ou concluir; “enquanto” pode indicar tempo ou contraste. Em reescrita, mantenha a relação lógica original e verifique se o modo verbal continua adequado.', example: '“Embora chovesse, houve atendimento” expressa concessão. Trocar “embora” por “porque” muda a lógica para causa.', examFocus: 'Explique a relação com suas próprias palavras antes de escolher o conectivo equivalente.' }
  ],
  'pt-periodos': [
    { title: 'Conte orações com segurança', objective: 'Distinguir frase, oração e período simples ou composto.', lesson: 'Frase é um enunciado com sentido; oração contém verbo ou locução verbal; período é a frase organizada em uma ou mais orações e termina em pontuação final. Período simples tem uma oração; composto tem duas ou mais. Uma locução verbal forma um núcleo verbal e, em regra, uma oração.', example: '“A servidora vai revisar o relatório.” Há locução “vai revisar” e um período simples; “A servidora revisou e encaminhou o relatório” apresenta duas formas verbais coordenadas, com análise contextual.', examFocus: 'Identifique verbos e locuções antes de contar as orações.' },
    { title: 'Classifique a construção', objective: 'Separar orações coordenadas e subordinadas no período composto.', lesson: 'Depois de contar as orações, analise a dependência entre elas. Se cada uma mantém estrutura independente, há coordenação; se uma exerce função ou completa a outra, há subordinação. Orações reduzidas aparecem sem conjunção e com verbo no infinitivo, gerúndio ou particípio.', example: '“Ao chegar ao setor, registre o pedido.” “Ao chegar” é uma oração reduzida de infinitivo com valor temporal.', examFocus: 'Não conclua que existe subordinação só porque a oração vem depois; teste a função que ela exerce.' },
    { title: 'Resolva períodos extensos', objective: 'Mapear estrutura, conectivos e pontuação em itens longos.', lesson: 'Em períodos longos, marque os verbos, delimite cada oração e localize conectivos. Só então determine a oração principal e a função das dependentes. Em reescritas, preserve a relação entre as partes, o referente dos pronomes e a concordância verbal.', example: '“O pedido, que chegou ontem, será analisado quando a equipe concluir a triagem.” Há uma oração adjetiva intercalada e uma adverbial temporal; cada uma se liga a uma parte distinta.', examFocus: 'Faça o mapa sujeito–verbo–oração antes de julgar a alternativa.' }
  ],
  'pt-concordancia': [
    { title: 'Faça a concordância básica', objective: 'Relacionar verbo e sujeito e nome e determinantes.', lesson: 'Na concordância verbal, o verbo se ajusta ao núcleo do sujeito em pessoa e número. Na nominal, artigos, pronomes, numerais e adjetivos concordam com o substantivo a que se referem. Encontre o núcleo: palavras entre ele e o verbo podem distrair.', example: '“A lista de documentos chegou.” O núcleo do sujeito é “lista”; por isso, o verbo fica no singular.', examFocus: 'A concordância acompanha o núcleo, não necessariamente o substantivo mais próximo.' },
    { title: 'Enfrente sujeitos complexos', objective: 'Resolver concordância com sujeito composto, coletivo e expressões partitivas.', lesson: 'O sujeito composto pode levar o verbo ao plural; a posição dos núcleos e a relação de sentido podem permitir construções específicas. Coletivos e expressões como “a maioria de” exigem atenção ao núcleo e ao termo que vem depois. Em “um dos que”, observe a estrutura da oração relativa.', example: '“A maioria dos processos foi analisada” concorda com “maioria”; a concordância com “processos” também pode ocorrer em certos contextos de ênfase, conforme a construção.', examFocus: 'Não aplique uma regra de ouvido sem identificar a estrutura completa.' },
    { title: 'Resolva casos nominais e verbais', objective: 'Examinar concordância em construções especiais e reescritas.', lesson: 'Expressões como “é necessário”, “anexo”, “meio”, “bastante” e “menos” variam conforme a função. Verbos impessoais têm comportamento próprio; “haver” com sentido de existir é impessoal, enquanto “existir” concorda com o sujeito. Em questões de correção, localize todos os pontos de concordância, não apenas o destacado.', example: '“Há muitos pedidos” mantém “há” no singular; “Existem muitos pedidos” concorda com “pedidos”.', examFocus: 'Classifique a palavra (adjetivo, advérbio, verbo impessoal) antes de flexioná-la.' }
  ],
  'pt-regencia': [
    { title: 'Entenda a dependência', objective: 'Reconhecer complemento verbal e nominal e o papel da preposição.', lesson: 'Regência é a relação entre um termo regente e seu complemento. Verbos podem exigir complemento sem preposição, com preposição ou aceitar mais de uma construção com mudança de sentido. Nomes como “favorável”, “necessidade” e “respeito” também podem exigir preposição.', example: 'Na norma-padrão, “assistir ao evento” usa preposição quando “assistir” significa presenciar; o sentido de “assistir alguém” pode ser prestar assistência.', examFocus: 'O sentido do verbo vem antes da preposição: o mesmo verbo pode reger de modo diferente.' },
    { title: 'Memorize regências frequentes com contexto', objective: 'Aplicar regência de verbos e nomes em frases administrativas.', lesson: 'Estude cada regência junto de seu significado e de uma frase. “Preferir” relaciona uma preferência a outra; “obedecer” e “desobedecer” pedem complemento preposicionado na norma-padrão; “informar” admite mais de uma organização dos complementos. A preposição pode contrair-se com artigo e produzir crase.', example: '“O servidor obedeceu à orientação.” O verbo pede “a”; “orientação” aceita artigo feminino “a”, formando “à”.', examFocus: 'Procure a preposição exigida e depois confira artigo, pronome ou nome que vem em seguida.' },
    { title: 'Analise reescritas e sentidos', objective: 'Julgar correção e mudança semântica causadas pela regência.', lesson: 'Em uma reescrita, a retirada ou troca de preposição pode tornar a frase inadequada ou alterar o significado. Alguns verbos admitem mais de uma regência, mas não necessariamente com o mesmo sentido. Consulte a norma-padrão e evite declarar uma forma errada sem considerar o contexto e a acepção.', example: '“Visar ao cargo” significa ter o cargo como objetivo na construção formal tradicional; “visar o documento” significa rubricá-lo. A preposição acompanha a acepção.', examFocus: 'Marque o sentido pretendido, a forma regida e a consequência para a crase.' }
  ],
  'pt-crase': [
    { title: 'Entenda o acento grave', objective: 'Identificar a fusão de preposição “a” com artigo ou demonstrativo.', lesson: 'Crase não é um sinal colocado por causa do feminino: o acento grave marca, em muitos casos, a fusão da preposição “a” com o artigo feminino “a/as”. Primeiro verifique se o termo anterior exige preposição; depois, se o termo seguinte admite artigo. Se uma das partes faltar, não há essa fusão.', example: '“Entregou o formulário à servidora”: entregar algo a alguém; “a servidora” admite artigo. A junção resulta em “à”.', examFocus: 'Use o teste do masculino: se a construção vira “ao”, isso é indício de crase no feminino.' },
    { title: 'Aplique testes e casos comuns', objective: 'Usar crase com locuções, horas, demonstrativos e nomes próprios.', lesson: 'Locuções adverbiais, prepositivas e conjuntivas femininas frequentemente recebem acento grave. Antes de horas determinadas, em geral há crase; diante de demonstrativos iniciados por “a” (“aquele”, “aquela”, “aquilo”), pode ocorrer a fusão. Nomes próprios e lugares variam conforme aceitem artigo.', example: '“A reunião começa às 14 horas” indica horário determinado; “voltou a estudar” não tem artigo feminino antes do infinitivo.', examFocus: 'Veja a regência e o artigo; não aplique crase apenas porque aparece uma palavra feminina.' },
    { title: 'Resolva proibições e ambiguidades', objective: 'Justificar a presença ou ausência de crase em período completo.', lesson: 'Não ocorre crase antes de verbo, palavra masculina, pronomes que não admitem artigo e expressões repetidas. Em nomes de lugar, teste “voltar da” ou “voltar de”. Em paralelismo, verifique se a preposição se repete ou se a construção oferece artigo. O sentido pode mudar a análise.', example: '“Começou a revisar” não recebe crase antes de verbo; “entregou a documentação à chefia” pode recebê-la por regência e artigo.', examFocus: 'Faça dois testes separados: o termo anterior pede “a”? O termo seguinte aceita artigo “a”?' }
  ],
  'lm-organica': [
    { title: 'Aprenda a estrutura da Lei Orgânica', objective: 'Compreender os fundamentos municipais e localizar dispositivos no texto oficial.', lesson: 'Na 4ª edição oficial consultada (2011), os arts. 1º a 4º tratam de fundamentos e direitos; os arts. 5º a 11 organizam o Município; os arts. 12 a 14 tratam de competências privativas, comuns e suplementares. O art. 6º apresenta Executivo e Legislativo como Poderes municipais. Use esses dados como orientação de estudo e confirme emendas posteriores antes de memorizar a redação vigente.', example: 'O art. 12 reúne competências próprias do Município; o art. 13 lista competências comuns com União e Estado; o art. 14 trata de suplementação normativa. A classificação ajuda a não trocar os três campos.', examFocus: 'A edição consultada é de 2011; o texto e as emendas atualizadas do edital devem prevalecer.' },
    { title: 'Estude a estrutura e compare dispositivos', objective: 'Relacionar organização municipal, Administração e Poderes com os assuntos do edital.', lesson: 'Na edição de 2011, os arts. 16 a 23 abrem as disposições de Administração Pública; os arts. 24 a 31 tratam de servidores; os arts. 37 a 79 organizam matérias do Legislativo e do processo legislativo; os arts. 80 a 102 tratam do Executivo e órgãos de apoio. Use o sumário para estudar por blocos e confira emendas posteriores. Faça uma ficha com assunto, ente competente e exceções expressas.', example: 'Ao comparar dois artigos, registre regra, quem decide e limite ou exceção. Isso ajuda a perceber alternativas que trocam competência do Executivo pela da Câmara.', examFocus: 'Esses intervalos pertencem à edição consultada; confirme se a versão do edital preserva a mesma organização.' },
    { title: 'Faça revisão literal avançada', objective: 'Resolver itens por confronto direto com o texto, sem extrapolar princípios.', lesson: 'Para cada afirmação, decomponha a frase em sujeito, verbo, objeto, condição e exceção. Compare palavra por palavra com o dispositivo. Termos absolutos e pequenas trocas (“poderá” por “deverá”, “privativa” por “comum”) mudam a regra. Se a edição disponível não confirmar a resposta, suspenda o julgamento e consulte a Câmara Municipal.', example: 'Uma alternativa pode acertar o tema e errar apenas o órgão responsável. Confirme quem pratica o ato no artigo antes de marcar.', examFocus: 'Use somente texto oficial atualizado; versões antigas servem para orientação de leitura, nunca para afirmar redação vigente.' }
  ],
  'lm-estatuto': [
    { title: 'Conheça o vínculo e o ingresso', objective: 'Compreender servidor, cargo, provimento, posse e exercício no texto de estudo da Lei 1.060/2011.', lesson: 'Na versão enviada, o art. 1º institui o regime para servidores do Município, autarquias e fundações; o art. 2º define servidor como pessoa legalmente investida em cargo público; o art. 3º define cargo como conjunto de atribuições e responsabilidades. O art. 6º estabelece a posse como momento da investidura. O art. 8º enumera formas de provimento. Os arts. 12, 13 e 20 tratam, respectivamente, da validade do concurso, da posse e do estágio probatório. A capa informa alteração pela Lei 1.366/2017; confira se há mudanças posteriores antes de usar prazos e redação literal.', example: 'A sequência conceitual é: ato de nomeação, posse e entrada em exercício. Na versão enviada, o art. 6º identifica a posse como investidura; não confunda esses marcos.', examFocus: 'A fonte de estudo informa alteração até 2017; confira a redação vigente no material oficial do edital antes de memorizar prazo ou artigo.' },
    { title: 'Organize direitos, vantagens e afastamentos', objective: 'Localizar e comparar regras funcionais no texto legal.', lesson: 'Faça uma tabela por assunto: jornada e frequência; remuneração e vantagens; férias; licenças; afastamentos; movimentação e vacância. Para cada instituto, registre requisitos, duração, autoridade responsável e efeito funcional apenas quando o texto os disser. Alterações podem revogar ou modificar parágrafos, por isso anote o dispositivo e a lei que alterou.', example: 'Não transfira automaticamente para Queimados o prazo de licença de outro Município ou do regime federal. Localize o artigo da Lei 1.060/2011 e confira se há alteração posterior.', examFocus: 'Evite decorar resumos sem artigo e sem atualização. Se o dispositivo não estiver no material consultado, não invente a resposta.' },
    { title: 'Domine deveres e regime disciplinar', objective: 'Interpretar proibições, responsabilidades, penalidades e procedimentos sem confundir conceitos.', lesson: 'Leia deveres, proibições, acumulação, responsabilidades e penalidades em blocos distintos. Depois confira o procedimento disciplinar, competência, defesa e prazos no texto atualizado. Diferencie desligamento administrativo de penalidade disciplinar quando a lei fizer essa distinção. Uma questão literal exige que cada elemento do enunciado tenha suporte no dispositivo.', example: 'Em um caso hipotético, separe fato, dever possivelmente violado, autoridade e procedimento. Não conclua que há penalidade sem base legal expressa.', examFocus: 'Artigo, hipótese e consequência precisam coincidir; gabaritos de lei sem fonte verificável não devem ser usados.' }
  ],
  'esp-administracao-publica': [
    { title: 'Entenda o que é Administração Pública', objective: 'Distinguir função administrativa, governo e princípios constitucionais.', lesson: 'Administração Pública é a atividade e o conjunto de órgãos e entidades que executam políticas e serviços públicos. O agente atua em nome do Estado e deve perseguir finalidade pública. Os princípios do art. 37 da Constituição são legalidade, impessoalidade, moralidade, publicidade e eficiência; eles orientam a atuação e ajudam a avaliar situações concretas.', example: 'Um servidor não pode escolher um requerimento para favorecer conhecido: a decisão deve seguir critérios públicos e impessoais.', examFocus: 'Associe cada situação ao princípio realmente violado; uma conduta pode afetar mais de um.' },
    { title: 'Compare organização e atos', objective: 'Diferenciar administração direta e indireta e reconhecer elementos dos atos administrativos.', lesson: 'Administração direta reúne órgãos das pessoas políticas; administração indireta reúne entidades com personalidade própria, como autarquias, fundações públicas, empresas públicas e sociedades de economia mista. Ato administrativo é manifestação estatal que produz efeitos jurídicos. Para analisá-lo, verifique competência, finalidade, forma, motivo e objeto; atributos e espécies são noções de prova e dependem da classificação estudada.', example: 'Uma secretaria municipal é órgão da administração direta; uma autarquia municipal é entidade da administração indireta.', examFocus: 'Não confunda órgão sem personalidade com entidade administrativa dotada de personalidade.' },
    { title: 'Aplique poderes e controle', objective: 'Resolver casos sobre poder vinculado, discricionário, hierárquico, disciplinar e de polícia.', lesson: 'Poder administrativo é instrumento para cumprir a lei e o interesse público, não privilégio pessoal. Poder hierárquico organiza e coordena; disciplinar apura infrações funcionais; polícia limita atividades em benefício coletivo; regulamentar detalha a execução da lei dentro dos limites legais. Discricionariedade permite escolha dentro da lei; não autoriza arbitrariedade. Atos podem ser controlados quanto à legalidade.', example: 'Se uma autoridade escolhe critério sem base normativa para beneficiar pessoa específica, não é discricionariedade legítima: há desvio da finalidade e da impessoalidade.', examFocus: 'Identifique a finalidade, o limite legal e o instrumento usado pela Administração.' }
  ],
  'esp-administracao-geral': [
    { title: 'Aprenda as funções administrativas', objective: 'Explicar planejamento, organização, direção e controle.', lesson: 'Planejar define objetivos e caminhos; organizar distribui tarefas e recursos; dirigir orienta pessoas e execução; controlar compara resultado e meta e corrige desvios. As funções se relacionam e formam um ciclo, não etapas isoladas. Em questões, observe qual ação está sendo descrita.', example: 'Definir prazo e meta para reduzir pendências é planejamento; distribuir tarefas entre servidores é organização; acompanhar o resultado é controle.', examFocus: 'Distingua a decisão de estabelecer a meta do acompanhamento do que foi realizado.' },
    { title: 'Desenhe processos e rotinas', objective: 'Ler organogramas, fluxogramas e métodos de trabalho.', lesson: 'Organograma representa relações e níveis de responsabilidade. Fluxograma mostra sequência de atividades, decisões e caminhos. Rotina descreve procedimentos recorrentes com entradas, responsáveis e saídas. Organização e Métodos procura simplificar fluxos, reduzir retrabalho e esclarecer responsabilidades sem eliminar controles necessários.', example: 'Um fluxograma de protocolo pode mostrar recebimento, conferência, registro, encaminhamento e devolução por pendência.', examFocus: 'Símbolos e setas mostram sequência; losangos normalmente representam decisões com caminhos alternativos.' },
    { title: 'Melhore gestão por processos', objective: 'Analisar gargalos, indicadores e melhoria contínua.', lesson: 'Processo transforma entradas em resultados para um usuário interno ou externo. Mapeie início, fim, responsáveis, regras, esperas e retrabalho. Uma melhoria precisa ser medida por indicador, como tempo médio ou percentual de pendências, e acompanhada para verificar efeitos colaterais. Padronizar ajuda, mas o processo deve ser revisto com evidências.', example: 'Se a conferência de documentos gera devoluções, classifique os motivos e atualize a orientação ao público; depois compare a taxa de devolução antes e depois.', examFocus: 'Uma proposta de melhoria deve atacar causa observada e incluir medida de resultado.' }
  ],
  'esp-recursos-humanos': [
    { title: 'Conheça o ciclo de pessoas', objective: 'Distinguir recrutamento, seleção, integração e desenvolvimento.', lesson: 'Recrutamento atrai candidatos; seleção compara requisitos e evidências para escolher; integração apresenta a pessoa à equipe e às rotinas. Treinamento desenvolve competências para tarefas atuais; desenvolvimento prepara crescimento mais amplo. No serviço público, ingresso em cargo efetivo depende das regras constitucionais e legais, não de escolha informal do setor.', example: 'Divulgar uma vaga é recrutamento; aplicar critérios previstos para avaliar candidatos é seleção.', examFocus: 'A questão costuma inverter atração de candidatos e escolha entre eles.' },
    { title: 'Acompanhe desempenho e rotinas', objective: 'Entender avaliação, frequência, férias e registros funcionais.', lesson: 'Avaliação de desempenho precisa de critérios ligados às atribuições, evidências e devolutiva. Rotinas de pessoal registram frequência, afastamentos, férias e alterações funcionais segundo as normas do órgão. Registros devem ser completos, íntegros, atualizados e acessíveis apenas a quem tem autorização.', example: 'Um apontamento de frequência deve registrar o fato com data e procedimento definido, sem julgamento pessoal do servidor.', examFocus: 'Diferencie avaliar resultado de punir; avaliação requer critérios e processo adequado.' },
    { title: 'Aplique gestão ética de pessoas', objective: 'Resolver situações de desenvolvimento, feedback e tratamento de dados.', lesson: 'Uma gestão responsável identifica necessidades, planeja capacitação, oferece feedback específico e acompanha resultados. Dados funcionais são informações pessoais e devem ser tratados com finalidade e acesso adequados. Processos devem observar impessoalidade, igualdade, normas do serviço e respeito nas relações de trabalho.', example: 'Em vez de “você é desorganizado”, um feedback útil aponta que três relatórios foram entregues após o prazo, explica o impacto e combina uma ação de acompanhamento.', examFocus: 'Prefira evidência observável, critério relacionado à função e tratamento respeitoso.' }
  ],
  'esp-materiais': [
    { title: 'Siga o ciclo do material', objective: 'Entender solicitação, compra, recebimento, guarda e distribuição.', lesson: 'A gestão de materiais busca disponibilidade com uso responsável dos recursos. O fluxo começa pela identificação da necessidade, segue para especificação e aquisição conforme o procedimento, passa por recebimento e conferência, armazenamento e distribuição. Cada etapa precisa de registro e definição de responsabilidade.', example: 'Ao receber caixas de material, confira quantidade e especificação com o pedido; registre divergência antes de liberar o recebimento.', examFocus: 'Não misture solicitação com autorização, nem recebimento físico com conferência documental.' },
    { title: 'Controle estoque e patrimônio', objective: 'Distinguir estoque de bens permanentes e aplicar inventário.', lesson: 'Estoque registra entradas, saídas e saldo de itens de consumo. Ponto de reposição sinaliza quando iniciar nova aquisição; estoque de segurança protege contra variação de demanda ou prazo. Patrimônio controla bens duráveis individualizados, localização, responsável, movimentação e estado de conservação. Inventário compara registros com a existência real.', example: 'Canetas são controladas como material de consumo; um computador é bem permanente e deve ser identificado e acompanhado patrimonialmente.', examFocus: 'Inventariar é conferir e registrar; não é simplesmente contar e descartar diferenças.' },
    { title: 'Reduza perdas com dados', objective: 'Analisar consumo, armazenamento e responsabilidades.', lesson: 'Boas decisões consideram demanda, prazo de reposição, custo, criticidade e espaço. Armazenamento protege contra dano, extravio e acesso indevido. A curva ABC pode priorizar controle conforme valor de consumo, mas o método não substitui criticidade operacional. Toda baixa, transferência ou divergência patrimonial precisa seguir o procedimento autorizado.', example: 'Um item barato, mas essencial e de reposição demorada, pode exigir atenção maior que seu valor financeiro sugere.', examFocus: 'Não aplique uma técnica mecanicamente; relacione o indicador ao risco e à finalidade do material.' }
  ],
  'esp-orcamento': [
    { title: 'Leia o orçamento público', objective: 'Compreender finalidade e ciclo do orçamento.', lesson: 'Orçamento público estima receitas e fixa despesas para um período, autorizando e organizando a ação estatal dentro das normas. A sequência de planejamento e orçamento integra planos, diretrizes e lei orçamentária anual. Administração financeira executa e acompanha recursos conforme autorização, finalidade e controles.', example: 'Uma unidade identifica necessidade de comprar material, mas só pode executar a despesa observando dotação, procedimento e autorização aplicáveis.', examFocus: 'Orçamento não é dinheiro em caixa; é instrumento legal de planejamento e autorização.' },
    { title: 'Diferencie receita, despesa e execução', objective: 'Reconhecer estágios básicos e documentos de controle.', lesson: 'Receita pública é ingresso arrecadado ou destinado ao Estado conforme a norma; despesa pública é aplicação autorizada de recursos. Em regra, a execução da despesa passa por empenho, liquidação e pagamento: compromisso orçamentário, verificação do direito do credor e quitação. A sequência precisa ser entendida sem trocar seus significados.', example: 'Receber o material e verificar a nota fiscal se relaciona à liquidação; pagar é etapa posterior, após as condições legais.', examFocus: 'Grave a ordem e o que se comprova em cada estágio.' },
    { title: 'Acompanhe execução e controles', objective: 'Analisar gastos, saldos e prestação de contas.', lesson: 'Controle financeiro compara o que foi autorizado, comprometido, entregue e pago. Indicadores e relatórios devem permitir rastrear finalidade, documento, responsável, período e saldo. Eficiência significa alcançar resultado com uso responsável; não significa cortar gasto necessário sem avaliar impacto.', example: 'Uma planilha de execução deve reconciliar total empenhado, liquidado e pago com documentos e saldo, explicando diferenças temporárias.', examFocus: 'Confira competência, etapa da despesa e documento comprobatório antes de concluir irregularidade.' }
  ],
  'esp-arquivologia': [
    { title: 'Entenda o que é arquivo', objective: 'Distinguir documento, arquivo, protocolo e fase documental.', lesson: 'Documento registra uma atividade ou decisão. Arquivo é o conjunto orgânico de documentos produzidos e recebidos por uma instituição no exercício de suas atividades, preservado para uso e prova. Protocolo controla recebimento, registro, classificação inicial, tramitação e expedição. O documento percorre fases conforme frequência de uso e destinação.', example: 'Um requerimento recebido pelo órgão é registrado e encaminhado; o processo resultante deve manter vínculo e sequência dos documentos relacionados.', examFocus: 'Arquivo não é apenas um local ou uma coleção de papéis sem relação.' },
    { title: 'Classifique, organize e conserve', objective: 'Aplicar classificação e métodos de arquivamento com contexto.', lesson: 'Classificar agrupa documentos conforme funções e atividades; ordenar estabelece sequência dentro do conjunto. A organização precisa preservar contexto, autenticidade e possibilidade de recuperação. Conservação reduz riscos físicos e digitais; descarte só ocorre conforme instrumentos e autorização aplicáveis.', example: 'Classificar processos por função administrativa mantém juntos documentos que registram a mesma atividade, mesmo que tenham datas diferentes.', examFocus: 'Organizar não significa separar apenas por cor ou assunto escolhido sem relação com a atividade.' },
    { title: 'Controle documentos digitais', objective: 'Acompanhar autenticidade, acesso, metadados e destinação.', lesson: 'Arquivo digital também exige classificação, metadados, controle de versão, integridade, acesso, cópia de segurança e plano de preservação. Digitalizar não elimina o original nem define automaticamente seu prazo de guarda. A gestão deve manter rastreabilidade da tramitação e respeitar a tabela de temporalidade vigente.', example: 'Uma imagem escaneada sem identificação, data, produtor ou vínculo ao processo pode ser difícil de provar e localizar.', examFocus: 'Tecnologia apoia a gestão; regras de classificação e destinação continuam necessárias.' }
  ],
  'esp-redacao-oficial': [
    { title: 'Escreva para o leitor entender', objective: 'Aplicar clareza, precisão, concisão e formalidade.', lesson: 'Redação oficial comunica decisões, pedidos e informações institucionais com clareza, objetividade, impessoalidade e padrão formal. Clareza evita ambiguidades; concisão elimina repetições sem retirar informação; precisão escolhe termos adequados. Formalidade não exige palavras rebuscadas.', example: 'Em vez de “vimos através deste informar que”, escreva “Informamos que o atendimento começará às 9 horas”.', examFocus: 'A melhor redação é a que transmite a informação necessária sem duplo sentido.' },
    { title: 'Estruture expedientes', objective: 'Reconhecer finalidade, destinatário e organização de comunicações oficiais.', lesson: 'Antes de redigir, identifique quem comunica, para quem, com qual finalidade e qual providência se espera. Ofício comunica formalmente entre autoridades e cidadãos conforme padrões do manual aplicável; relatório organiza fatos, análise e encaminhamentos. Modelos e denominações de expediente podem variar entre órgãos, então siga o edital e o manual indicado.', example: 'Um relatório de ocorrência deve separar fatos observados, providências adotadas e pendências, sem misturar opinião com registro.', examFocus: 'Identifique propósito e destinatário antes de escolher formato e tratamento.' },
    { title: 'Revise como a banca cobra', objective: 'Corrigir linguagem, coesão e adequação ao Manual de Redação.', lesson: 'Revise em três passagens: conteúdo e completude; sequência lógica e referentes; norma-padrão, pontuação e apresentação. Evite expressões vagas, redundâncias e tratamento inadequado. O Manual de Redação da Presidência é fonte de referência federal; confirme no edital quais trechos e padrões serão cobrados para o Município.', example: 'Se o texto usa “ele” e há dois possíveis antecedentes, substitua o pronome pelo nome ou reorganize a frase para eliminar a dúvida.', examFocus: 'Clareza, impessoalidade e adequação são critérios; não confunda formalidade com excesso de fórmulas.' }
  ],
  'esp-normas': [
    { title: 'Leia uma norma com método', objective: 'Localizar âmbito, destinatário, comando e condição.', lesson: 'Uma norma pode ser organizada em artigos, parágrafos, incisos e alíneas. Localize quem está sujeito, qual conduta é exigida ou permitida, em que situação e com qual consequência. Leia definições e regras gerais antes das exceções. Não conclua que uma regra vale para outro órgão ou ente sem conferir seu âmbito.', example: 'Uma instrução interna aplicável a uma secretaria não se estende automaticamente a toda a Prefeitura.', examFocus: 'Marque sujeito, verbo do comando, condição e alcance da regra.' },
    { title: 'Interprete e aplique procedimentos', objective: 'Distinguir obrigação, permissão, proibição e competência.', lesson: '“Deve” e “é vedado” indicam comandos diferentes de “pode” ou “é facultado”. Competência aponta quem pode praticar o ato; procedimento define etapas e registros. Em caso de conflito aparente, confira hierarquia, especialidade e vigência da norma com fonte oficial e encaminhe dúvida jurídica à unidade competente.', example: 'Se um formulário pede assinatura de autoridade específica, o agente não deve substituir essa validação por decisão própria.', examFocus: 'Não confunda opinião administrativa com autorização normativa.' },
    { title: 'Resolva casos sem extrapolar', objective: 'Aplicar normas a situações concretas com registro e controle.', lesson: 'Para resolver um caso, identifique fatos comprovados, norma aplicável, autoridade, procedimento e registro necessário. A interpretação deve respeitar texto, finalidade e limites de competência. Quando a norma não estiver no material fornecido, não invente prazo, sanção ou exceção: procure a fonte vigente.', example: 'Diante de documentação incompleta, registre a pendência e siga o fluxo para solicitar complementação conforme a regra do órgão.', examFocus: 'Uma resposta administrativa segura mostra base, responsável e próximo passo permitido.' }
  ],
  'esp-planejamento-controle': [
    { title: 'Transforme objetivo em ação', objective: 'Elaborar plano com meta, atividade, responsável e prazo.', lesson: 'Um plano de ação parte de problema definido e resultado esperado. Especifique atividades, responsáveis, prazo, recursos, evidência de conclusão e riscos. Uma meta deve permitir verificar avanço; frases como “melhorar o atendimento” precisam ser convertidas em medida observável.', example: 'Meta: reduzir pedidos devolvidos por falta de documento até determinada data; ação: revisar orientação e treinar equipe; indicador: percentual de devolução.', examFocus: 'Ação sem responsável, prazo e medida não permite acompanhamento efetivo.' },
    { title: 'Monitore execução e indicadores', objective: 'Comparar metas, dados e resultados físicos e financeiros.', lesson: 'Controle acompanha se a execução ocorreu conforme o plano, identifica desvios e orienta correção. Indicadores devem ter definição, fonte, periodicidade e responsável. Análise física observa entregas e atividades; análise financeira acompanha recursos e gastos. Compare períodos equivalentes e registre limitações dos dados.', example: 'O número de atendimentos é uma medida de volume; para avaliar qualidade, pode ser necessário acompanhar tempo, retorno ou satisfação, com critério claro.', examFocus: 'Indicador mede algo definido; não conclua causalidade só porque dois números variaram juntos.' },
    { title: 'Relate e corrija desvios', objective: 'Produzir relatório com evidência, análise e encaminhamento.', lesson: 'Relatório gerencial deve apresentar contexto, fonte dos dados, comparação com meta, causas prováveis, limitações e proposta de ação. Separe fato de interpretação. Depois da correção, acompanhe se o resultado melhorou e se não surgiu novo problema. Controle é ciclo de aprendizagem e prestação de contas.', example: 'Em vez de “o setor falhou”, registre que 18 de 60 processos ultrapassaram o prazo e descreva quais etapas concentraram a espera.', examFocus: 'Use números rastreáveis e recomendações ligadas aos dados observados.' }
  ],
  'esp-etica': [
    { title: 'Comece pelos deveres do atendimento', objective: 'Agir com urbanidade, imparcialidade, respeito e responsabilidade.', lesson: 'Ética no serviço público orienta decisões para o interesse público e o respeito às pessoas. Atendimento adequado exige escuta, linguagem compreensível, tratamento igual e encaminhamento correto. Impessoalidade proíbe favorecimento; urbanidade exige respeito; responsabilidade exige cuidado com informação e recursos.', example: 'Se duas pessoas apresentam pedidos equivalentes, a ordem e os critérios devem ser os mesmos, ressalvadas prioridades previstas em norma.', examFocus: 'A alternativa correta tende a combinar respeito, regra comum e registro do atendimento.' },
    { title: 'Resolva dilemas cotidianos', objective: 'Reconhecer conflito de interesse, sigilo e uso de recursos públicos.', lesson: 'Servidor deve separar interesse privado do dever funcional, proteger informações legalmente sigilosas e usar recursos do órgão para finalidades públicas. Transparência não significa divulgar indiscriminadamente dado protegido. Diante de dúvida ou pressão indevida, registre o ocorrido e procure canal institucional adequado.', example: 'Não é apropriado consultar cadastro funcional por curiosidade; o acesso precisa estar ligado a uma tarefa autorizada.', examFocus: 'Avalie finalidade, autorização, igualdade de tratamento e necessidade de registro.' },
    { title: 'Mantenha conduta profissional', objective: 'Aplicar ética em relações, comunicação e prestação de contas.', lesson: 'Conduta ética inclui cumprir deveres, comunicar limitações, corrigir erro e tratar colegas e cidadãos sem discriminação. Um erro deve ser informado e corrigido pelo procedimento correto; ocultá-lo tende a ampliar o dano. Responsabilidade pode ser administrativa, civil ou penal conforme a lei e os fatos, sem presumir consequência automática.', example: 'Ao perceber que encaminhou um processo ao setor errado, informe a chefia, registre a correção e redirecione pelo fluxo formal.', examFocus: 'Procure a conduta que protege o cidadão, o serviço e a rastreabilidade.' }
  ],
  'esp-informatica': [
    { title: 'Construa a base digital', objective: 'Distinguir informação, arquivo, programa, dispositivo e rede.', lesson: 'Informática reúne dispositivos, programas e procedimentos usados para registrar, processar, armazenar e comunicar informações. Hardware corresponde aos componentes físicos; software, aos programas e instruções. Dados precisam de organização, integridade, disponibilidade e controle de acesso. Como o edital não especifica produto ou versão, este curso fica nos conceitos gerais.', example: 'Um arquivo é uma unidade de informação armazenada; o programa usado para abri-lo é software; o computador é hardware.', examFocus: 'Mantenha a resposta no nível conceitual autorizado pelo edital; não presuma um sistema operacional específico.' },
    { title: 'Trabalhe com arquivos e segurança', objective: 'Aplicar práticas gerais de organização, proteção e uso responsável.', lesson: 'Organize arquivos com nomes compreensíveis, pastas coerentes e versões identificáveis. Faça cópias de segurança conforme orientação institucional e proteja credenciais. Desconfie de links e anexos inesperados, bloqueie a tela ao se afastar e compartilhe apenas com pessoas autorizadas. Segurança combina tecnologia, processo e comportamento.', example: 'Uma cópia de segurança guardada apenas no mesmo equipamento pode ser perdida junto com o original; siga o procedimento de armazenamento aprovado.', examFocus: 'Segurança não é apenas instalar programa: inclui controle de acesso, cópia e atenção do usuário.' },
    { title: 'Avalie situações de uso', objective: 'Resolver casos de informação, comunicação e proteção de dados.', lesson: 'Ao lidar com informação pública, siga regras de acesso e proteção de dados. Verifique destinatário antes de enviar, use canais institucionais e preserve registros necessários. Em problemas de acesso, perda de arquivo ou mensagem suspeita, interrompa a ação de risco e acione o suporte responsável. Não aplique comandos de ferramenta que o edital não nomeia.', example: 'Antes de enviar uma planilha, confirme se o destinatário está autorizado e se as colunas incluem dados pessoais desnecessários.', examFocus: 'A melhor conduta reduz exposição e mantém o serviço rastreável.' }
  ]
};

export function getCourseUnits(topic: SyllabusTopic) {
  return courseUnits[topic.id];
}
